//! Oracle goldens for the decompression direction — no Erlang needed at run time.
//!
//! Every `G_*` constant below is a byte image produced by the system `erl`
//! (OTP 29.1.1 / erts-17.1) and pasted here verbatim, so these tests are a permanent
//! record of what zlib 1.3.2 emitted for the corresponding input. The block is
//! machine-generated data and deliberately long; that is why this file is larger than
//! the crate's ~1000-line guideline (see the crate `CONTEXT.md`).
//!
//! The plaintexts are goldens too. `mixed(n)` and `rep40k()` are regenerated in Rust
//! instead of being pasted (40 KiB of decimal bytes would bury the tests); the small
//! ones are pasted, and `mixed4k_plain` pins `mixed()` against the oracle.
//!
//! The `G_*` images are pasted verbatim from the oracle, one per oracle case, and their
//! names are generated (lower-case, `G_`-prefixed) so a case name maps onto a constant
//! without a rename step; the convention `non_upper_case_globals` is allowed for that.
#![allow(non_upper_case_globals)]
//!
//! Coverage: the three framings zlib produces (`compress` → zlib/RFC 1950, `zip` → raw
//! RFC 1951, `gzip` → RFC 1952) over literal-only, run-length, structured and
//! >32 KiB bodies; the level/strategy matrix (`level 0` stored, `level 1`/`9` dynamic,
//! `huffman_only`, `rle`, `filtered`, each with its raw twin); and the preset-dictionary
//! protocol.

use beam_deflate::inflate::decompress_all;
use beam_deflate::{Flush, Inflate, Status};

/// zlib / RFC 1950 (`zlib:compress/1`, `zlib:uncompress/1`).
const ZLIB: i8 = 15;
/// zlib with the window size taken from the header (`CMF`).
const ZLIB_HEADER_WINDOW: i8 = 0;
/// raw deflate / RFC 1951 (`zlib:zip/1`, `zlib:unzip/1`).
const RAW: i8 = -15;
/// gzip / RFC 1952 (`zlib:gzip/1`, `zlib:gunzip/1`).
const GZIP: i8 = 16 + 15;
/// auto-detect zlib or gzip.
const AUTO: i8 = 32 + 15;

