/// adler32 of the preset dictionary
pub const G_DICT_ADLER: u32 = 1631326202;

// ---------------------------------------------------------------------------
// Regenerated plaintexts
// ---------------------------------------------------------------------------

/// The 600/4096-byte structured body the strategy matrix compresses: byte `i` is
/// `(i * 37 + i div 7) rem 256`.
fn mixed(n: usize) -> Vec<u8> {
    (0..n).map(|i| ((i * 37 + i / 7) % 256) as u8).collect()
}

/// The 40 KiB repetitive body: `<<"abcdefgh">>` repeated 5120 times.
fn rep40k() -> Vec<u8> {
    b"abcdefgh".repeat(5120)
}

/// One-shot decode with a generous bound (the largest golden body is 40 KiB).
fn decode(window_bits: i8, image: &[u8]) -> Vec<u8> {
    let (body, used) = decompress_all(window_bits, image, 1 << 20)
        .unwrap_or_else(|e| panic!("{window_bits} framing of a {} byte image: {e:?}", image.len()));
    assert_eq!(used, image.len(), "the whole image is one stream");
    body
}

// ---------------------------------------------------------------------------
// The framing matrix
// ---------------------------------------------------------------------------

/// Every zlib (`compress`) image decodes to its golden plaintext, both with an
/// explicit window and with the header-supplied one.
#[test]
fn zlib_images_decode_to_their_plaintexts() {
    for (image, plain) in [
        (G_empty_zlib, G_empty_plain),
        (G_abc_zlib, G_abc_plain),
        (G_zeros16_zlib, G_zeros16_plain),
        (G_a300_zlib, G_a300_plain),
        (G_mixed4k_zlib, G_mixed4k_plain),
    ] {
        assert_eq!(decode(ZLIB, image), plain);
        assert_eq!(decode(ZLIB_HEADER_WINDOW, image), plain);
        assert_eq!(decode(AUTO, image), plain, "auto-detect takes a zlib member");
    }
    assert_eq!(decode(ZLIB, G_rep40k_zlib), rep40k());
}

/// Every raw (`zip`) image decodes to its golden plaintext. `-15` is the
/// `zlib:unzip/1` framing; there is no header, no trailer and no checksum to verify.
#[test]
fn raw_images_decode_to_their_plaintexts() {
    for (image, plain) in [
        (G_empty_zip, G_empty_plain),
        (G_abc_zip, G_abc_plain),
        (G_zeros16_zip, G_zeros16_plain),
        (G_a300_zip, G_a300_plain),
        (G_mixed4k_zip, G_mixed4k_plain),
    ] {
        assert_eq!(decode(RAW, image), plain);
    }
    assert_eq!(decode(RAW, G_rep40k_zip), rep40k());
}

/// A raw stream is not a zlib stream: the same bytes under `15` are a header error,
/// which is how the two `zlib` entry points stay distinguishable.
#[test]
fn a_raw_image_is_not_a_zlib_image() {
    assert!(decompress_all(ZLIB, G_abc_zip, 1024).is_err());
    assert!(decompress_all(RAW, G_abc_zlib, 1024).is_err());
}

/// Every gzip (`gzip`) image decodes to its golden plaintext, header and trailer
/// (CRC-32 + ISIZE) included, under `16 + 15` and under auto-detect.
#[test]
fn gzip_images_decode_to_their_plaintexts() {
    for (image, plain) in [
        (G_empty_gzip, G_empty_plain),
        (G_abc_gzip, G_abc_plain),
        (G_zeros16_gzip, G_zeros16_plain),
        (G_a300_gzip, G_a300_plain),
        (G_mixed4k_gzip, G_mixed4k_plain),
    ] {
        assert_eq!(decode(GZIP, image), plain);
        assert_eq!(decode(AUTO, image), plain, "auto-detect takes a gzip member");
    }
    assert_eq!(decode(GZIP, G_rep40k_gzip), rep40k());
}

/// The 40 KiB bodies are all the same plaintext through the three framings; they
/// also exercise a window that slides (the body is longer than 32 KiB).
#[test]
fn the_long_body_is_identical_through_all_three_framings() {
    let plain = rep40k();
    assert_eq!(plain.len(), 40 * 1024);
    assert_eq!(decode(ZLIB, G_rep40k_zlib), plain);
    assert_eq!(decode(RAW, G_rep40k_zip), plain);
    assert_eq!(decode(GZIP, G_rep40k_gzip), plain);
}

/// A window smaller than the compressor's still decodes a stream whose matches fit.
/// `-8` is a 256-byte window — enough for the run-length and 3-byte bodies.
#[test]
fn a_narrow_window_still_decodes_short_distance_matches() {
    assert_eq!(decode(-8, G_zeros16_zip), G_zeros16_plain);
    assert_eq!(decode(-8, G_abc_zip), G_abc_plain);
    // The 300-byte body uses distance-1 matches only, so it fits a 256-byte window.
    assert_eq!(decode(-8, G_a300_zip), G_a300_plain);
}

// ---------------------------------------------------------------------------
// Level and strategy matrix
// ---------------------------------------------------------------------------

/// The stored (`level 0`), dynamic (`level 1`/`9`), `huffman_only`, `rle` and
/// `filtered` streams all decode, framed and raw.
#[test]
fn the_level_and_strategy_variants_decode() {
    let small = mixed(600);
    let big = mixed(4096);
    assert_eq!(big, G_mixed4k_plain, "`mixed(4096)` is the oracle's body");
    for (image, plain) in [
        (G_mixed_lvl0, &small),
        (G_mixed_lvl1, &big),
        (G_mixed_lvl9, &big),
        (G_mixed_hoff, &small),
        (G_mixed_rle, &small),
        (G_mixed_filt, &big),
    ] {
        assert_eq!(&decode(ZLIB, image), plain);
    }
    for (image, plain) in [
        (G_mixed_lvl0_raw, &small),
        (G_mixed_lvl1_raw, &big),
        (G_mixed_lvl9_raw, &big),
        (G_mixed_hoff_raw, &small),
        (G_mixed_rle_raw, &small),
        (G_mixed_filt_raw, &big),
    ] {
        assert_eq!(&decode(RAW, image), plain);
    }
}

/// The `level 0` image is a **stored** block and the `level 9` one a **dynamic**
/// block, so both block shapes `inflate` has to take are exercised by a golden. (A
/// small incompressible body can make zlib choose either, which is why the assertion
/// names the level that pins the shape.)
#[test]
fn the_block_shapes_are_all_reachable() {
    // The first block starts at bit 0 of the first deflate byte, which follows the
    // two-byte zlib header: BFINAL is bit 0 and BTYPE is bits 1-2.
    assert_eq!(
        G_mixed_lvl0[2] & 0x06,
        0,
        "level 0 emits a stored block (BTYPE 00)"
    );
    assert_eq!(
        G_mixed_lvl9[2] & 0x06,
        0b10 << 1,
        "level 9 on a 4 KiB structured body emits a dynamic block (BTYPE 10)"
    );
    // All of them decode, so whichever block a stream uses is covered.
    assert_eq!(decode(ZLIB, G_mixed_lvl0), mixed(600));
    assert_eq!(decode(ZLIB, G_mixed_lvl9), mixed(4096));
    assert_eq!(decode(ZLIB, G_mixed_hoff), mixed(600));
    assert_eq!(decode(ZLIB, G_mixed_rle), mixed(600));
}

// ---------------------------------------------------------------------------
// The preset-dictionary protocol
// ---------------------------------------------------------------------------

/// A stream compressed against a preset dictionary reports `Z_NEED_DICT` with the
/// dictionary's Adler-32, and completes once that dictionary is installed.
#[test]
fn a_dictionary_stream_needs_and_then_uses_its_dictionary() {
    // The one-shot entry point has no way to supply a dictionary, so it refuses.
    assert!(decompress_all(ZLIB, G_mixed4k_dictstream, 1 << 20).is_err());

    let mut stream = Inflate::new(ZLIB).expect("zlib 15");
    let mut out = vec![0u8; 1 << 20];
    let pump = stream
        .inflate(G_mixed4k_dictstream, &mut out, Flush::None)
        .expect("pump");
    assert_eq!(pump.status, Status::NeedDict(G_DICT_ADLER));

    // A dictionary that does not hash to the id in the header is refused.
    assert!(stream.set_dictionary(b"not the fox").is_err());
    // The right one is accepted, and the stream resumes from the block after `DICT`.
    stream.set_dictionary(G_dict).expect("the right dictionary");
    let mut produced = 0usize;
    loop {
        let pump = stream
            .inflate(&G_mixed4k_dictstream[pump.consumed..], &mut out[produced..], Flush::None)
            .expect("pump");
        produced += pump.produced;
        match pump.status {
            Status::StreamEnd => break,
            Status::Ok => {}
            other => panic!("unexpected {other:?} after the dictionary"),
        }
    }
    assert_eq!(&out[..produced], G_mixed4k_plain);
    assert!(stream.at_stream_end());
}

/// The dictionary bytes are the window's history, so a raw stream started with one
/// can reference them without any header (`inflateSetDictionary`'s raw form).
#[test]
fn a_raw_stream_accepts_a_dictionary_before_its_first_block() {
    let mut stream = Inflate::new(RAW).expect("raw 15");
    stream.set_dictionary(G_dict).expect("a raw stream takes one");
    assert_eq!(stream.get_dictionary(), G_dict);
}

// ---------------------------------------------------------------------------
// The streaming pump
// ---------------------------------------------------------------------------

/// Pump `image` through a fresh stream in `in_chunk`-sized input slices and
/// `out_chunk`-sized output slices until `Z_STREAM_END`, asserting that no step
/// reports an error and that progress is always made.
fn pump_all(window_bits: i8, image: &[u8], in_chunk: usize, out_chunk: usize) -> Vec<u8> {
    let mut stream = Inflate::new(window_bits).expect("window bits");
    let mut buf = vec![0u8; out_chunk];
    let mut body = Vec::new();
    let mut consumed = 0usize;
    let mut steps = 0usize;
    loop {
        steps += 1;
        assert!(steps < 1 << 22, "the pump must terminate");
        let end = (consumed + in_chunk).min(image.len());
        let pump = stream
            .inflate(&image[consumed..end], &mut buf, Flush::None)
            .expect("pump");
        consumed += pump.consumed;
        body.extend_from_slice(&buf[..pump.produced]);
        match pump.status {
            Status::StreamEnd => {
                assert!(stream.at_stream_end());
                assert_eq!(consumed, image.len(), "the stream ends at the last byte");
                return body;
            }
            Status::Ok | Status::BufError => {
                assert!(
                    pump.consumed != 0 || pump.produced != 0,
                    "no progress at {consumed}/{} bytes of input",
                    image.len()
                );
            }
            other => panic!("step {steps} reported {other:?}"),
        }
    }
}

/// The stream is chunk-size agnostic: one input byte and one output byte at a time
/// produces exactly the same body as the one-shot route.
#[test]
fn a_byte_at_a_time_pump_decodes_the_same_body() {
    assert_eq!(pump_all(ZLIB, G_a300_zlib, 1, 1), G_a300_plain);
    assert_eq!(pump_all(ZLIB, G_mixed4k_zlib, 1, 3), G_mixed4k_plain);
    assert_eq!(pump_all(GZIP, G_mixed4k_gzip, 7, 5), G_mixed4k_plain);
    assert_eq!(pump_all(RAW, G_mixed4k_zip, 1, 1), G_mixed4k_plain);
}

/// The same body, whatever the chunking — the per-call chunking is observable
/// (`zlib:safeInflate/2` returns it), so the *total* must not depend on it.
#[test]
fn every_chunking_yields_the_same_body() {
    let plain = rep40k();
    for in_chunk in [1usize, 13, 1024, 4096, 1 << 20] {
        for out_chunk in [1usize, 64, 4096, 16384] {
            assert_eq!(
                pump_all(ZLIB, G_rep40k_zlib, in_chunk, out_chunk),
                plain,
                "in_chunk {in_chunk}, out_chunk {out_chunk}"
            );
        }
    }
}

/// `inflate` never writes past `output.len()` and never consumes past `input.len()`,
/// even when the buffers are tiny.
#[test]
fn the_pump_respects_its_buffer_bounds() {
    let mut stream = Inflate::new(ZLIB).expect("zlib 15");
    let mut out = [0u8; 2];
    let pump = stream
        .inflate(G_a300_zlib, &mut out, Flush::None)
        .expect("pump");
    assert_eq!(pump.produced, 2);
    assert!(pump.consumed <= G_a300_zlib.len());
    assert!(pump.produced <= out.len());
    // A zero-length output buffer makes no output progress and zlib calls that
    // `Z_BUF_ERROR` unless input was consumed.
    let pump = stream
        .inflate(&G_a300_zlib[pump.consumed..], &mut [], Flush::None)
        .expect("pump");
    assert_eq!(pump.produced, 0);
    assert_eq!(pump.consumed, 0, "a full output buffer stops the copy");
    assert_eq!(pump.status, Status::BufError);
}

/// `consumed` excludes bytes that follow the stream — the property
/// `binary_to_term/2`'s `used` option depends on.
#[test]
fn trailing_bytes_are_not_consumed() {
    for (bits, image) in [
        (ZLIB, G_mixed4k_zlib),
        (RAW, G_mixed4k_zip),
        (GZIP, G_mixed4k_gzip),
        (AUTO, G_mixed4k_gzip),
    ] {
        let mut with_junk = image.to_vec();
        with_junk.extend_from_slice(b"junk after the stream");
        let (body, used) = decompress_all(bits, &with_junk, 1 << 20).expect("decode");
        assert_eq!(body, G_mixed4k_plain);
        assert_eq!(used, image.len(), "{bits} framing");
    }
}

/// Every golden image is also a valid `decompress` (the crate's zlib-only
/// convenience form) after being framed as zlib.
#[test]
fn the_crate_level_decompress_matches_the_goldens() {
    assert_eq!(beam_deflate::decompress(G_abc_zlib).expect("decode"), b"abc");
    assert_eq!(
        beam_deflate::decompress(G_rep40k_zlib).expect("decode"),
        rep40k()
    );
}
